function.description:
Execute code to achieve a goal.

Available:
type ToolMockLookupInput = {
    /** The term to look up. */
    query: string;
    [key: string]: unknown;
}
type ToolMockLookupOutput = unknown
type ToolMockAddInput = {
    a: number;
    b: number;
    [key: string]: unknown;
}
type ToolMockAddOutput = unknown
type ToolMockFailInput = {
    reason?: string;
    [key: string]: unknown;
}
type ToolMockFailOutput = unknown
type ToolMockSlowInput = {
    /** Seconds to wait (default 2). */
    seconds?: number;
    [key: string]: unknown;
}
type ToolMockSlowOutput = unknown
type ToolMockChartInput = {
    [key: string]: unknown;
}
type ToolMockChartOutput = unknown
type ToolMockRepeatInput = {
    text: string;
    times: number;
    [key: string]: unknown;
}
type ToolMockRepeatOutput = unknown
type ToolTrackerListIssuesInput = {
    /** Which issues to list (default open). */
    state?: "open" | "closed" | "all";
    /** Only issues with this label. */
    label?: string;
    /** At most this many (default 20, at most 500). */
    limit?: number;
    [key: string]: unknown;
}
type ToolTrackerListIssuesOutput = {
    issues: {
        id: number;
        title: string;
        state: "open" | "closed";
        labels?: string[];
        [key: string]: unknown;
    }[];
    /** How many issues match. */
    total: number;
    [key: string]: unknown;
}
type ToolTrackerGetIssueInput = {
    /** The issue's id. */
    id: number;
    [key: string]: unknown;
}
type ToolTrackerGetIssueOutput = unknown
type ToolTrackerCreateIssueInput = {
    title: string;
    body?: string;
    labels?: string[];
    [key: string]: unknown;
}
type ToolTrackerCreateIssueOutput = {
    id: number;
    title?: string;
    url: string;
    [key: string]: unknown;
}
type ToolTrackerSearchInput = {
    /** Words to look for in titles. */
    query: string;
    [key: string]: unknown;
}
type ToolTrackerSearchOutput = unknown
type ToolTrackerDeleteInput = {
    id: number;
    [key: string]: unknown;
}
type ToolTrackerDeleteOutput = unknown

declare const codemode: {
	/**
	 * Look up a term in the reference catalog and return what it says.
	 * @param input.query - The term to look up.
	 */
	tool_mock_lookup: (input: ToolMockLookupInput) => Promise<ToolMockLookupOutput>;

	/**
	 * Add two numbers.
	 */
	tool_mock_add: (input: ToolMockAddInput) => Promise<ToolMockAddOutput>;

	/**
	 * Always fails, with an error result.
	 */
	tool_mock_fail: (input: ToolMockFailInput) => Promise<ToolMockFailOutput>;

	/**
	 * Waits some seconds before answering.
	 * @param input.seconds - Seconds to wait (default 2).
	 */
	tool_mock_slow: (input: ToolMockSlowInput) => Promise<ToolMockSlowOutput>;

	/**
	 * Draws a chart of the data.
	 */
	tool_mock_chart: (input: ToolMockChartInput) => Promise<ToolMockChartOutput>;

	/**
	 * Repeats a text.
	 */
	tool_mock_repeat: (input: ToolMockRepeatInput) => Promise<ToolMockRepeatOutput>;

	/**
	 * List issues, newest first. Filter by state or label.
	 * @param input.state - Which issues to list (default open).
	 * @param input.label - Only issues with this label.
	 * @param input.limit - At most this many (default 20, at most 500).
	 */
	tool_tracker_list_issues: (input: ToolTrackerListIssuesInput) => Promise<ToolTrackerListIssuesOutput>;

	/**
	 * Get one issue by id, with its body and comments.
	 * @param input.id - The issue's id.
	 */
	tool_tracker_get_issue: (input: ToolTrackerGetIssueInput) => Promise<ToolTrackerGetIssueOutput>;

	/**
	 * Create an issue.
	 */
	tool_tracker_create_issue: (input: ToolTrackerCreateIssueInput) => Promise<ToolTrackerCreateIssueOutput>;

	/**
	 * Search issue titles.
	 * @param input.query - Words to look for in titles.
	 */
	tool_tracker_search: (input: ToolTrackerSearchInput) => Promise<ToolTrackerSearchOutput>;

	/**
	 * Delete an issue.
	 */
	tool_tracker_delete: (input: ToolTrackerDeleteInput) => Promise<ToolTrackerDeleteOutput>;
}

Write an async arrow function in JavaScript that returns the result.
Do NOT use TypeScript syntax — no type annotations, interfaces, or generics.
Do NOT define named functions then call them — just write the arrow function body directly.

Example: async () => { const r = await codemode.searchWeb({ query: "test" }); return r; }

